package com.acme.catalog.entity; import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="products") public class Product { @Id @Column(length=50) private String sku; @Column(nullable=false) private String name; @Column(nullable=false,precision=12,scale=2) private BigDecimal price; @Column(nullable=false) private boolean active=true; protected Product(){} public Product(String sku,String name,BigDecimal price){this.sku=sku;this.name=name;this.price=price;} public String getSku(){return sku;}public String getName(){return name;}public BigDecimal getPrice(){return price;}public boolean isActive(){return active;} }
